type Boss={name:string;icon_url:string;pool_order?:number};
type DraftStep={step_number:number;actor_slot:"a"|"b";action:"ban"|"pick";resonator:string};
type Event={slug:string;title:string;boss:string;headline_boss?:string;bans_per_player?:number;soft_deleted_at?:string|null;status:string;format:string;event_date?:string|null;rules?:string;public_notice?:string;roster_published:number;bracket_published?:number;medals_published:number;has_artwork?:number};
type Person={id:string;display_name:string;resonator_icon:string};
type RosterEntry=Person&{state:string;published:number;seed_position?:number|null;reserve_order?:number|null};
function personOptionLabel(person:Person,people:Person[]){const base=person.display_name+" · "+person.resonator_icon;return people.filter(p=>p.display_name===person.display_name&&p.resonator_icon===person.resonator_icon).length>1?base+" · "+person.id.slice(0,6):base;}
type Match={phase_state?:string;hold_note?:string;started_without_details?:number;dependencies?:{dependsOnMatchId:string;dependencyType:string;targetSlot:string}[];match_boss?:string|null;boss_method?:string|null;clear_time_seconds?:number|null;staff_note?:string|null;id:string;round_number:number;round_label:string;match_order:number;bracket_position:number;bracket_side:string;state:string;participant_a:string|null;participant_b:string|null;winner_id:string|null;outcome:string;version:number;name_a:string|null;name_b:string|null};
function downstreamMatches(matches:Match[],matchId:string){const found=new Set<string>();let changed=true;while(changed){changed=false;for(const match of matches){if(found.has(match.id))continue;if((match.dependencies||[]).some(edge=>edge.dependsOnMatchId===matchId||found.has(edge.dependsOnMatchId))){found.add(match.id);changed=true}}}return matches.filter(match=>found.has(match.id));}
type Staff={id:string;label:string;role:string;revoked_at:string|null};
type Props={initialToken?:string;embedded?:boolean};
const resonators=["Carlotta","Cartethyia","Aemeath","Hiyuki","Chisa","Suoming","Jingran","Hsin","Qingxiao","Suisui","Lucy","Lucilla","Rebecca","Denia","Sigrika","Yangyang","Luuk Herssen","Mornye","Lynae","Qiuyuan","Galbrena","Iuno","Augusta","Phrolova","Lupa","Zani","Ciaccona","Cantarella","Phoebe","Brant","Roccia","Shorekeeper","Zhezhi","Changli","Xiangli Yao","Jinhsi","Yinlin","Camellya","Jiyan"];
async function imageData(file:FormDataEntryValue|null):Promise<string>{if(!(file instanceof File)||!file.size)throw new Error("Choose a tournament image.");if(file.size>1500000)throw new Error("Image must be 1.5 MB or smaller.");if(!["image/png","image/jpeg","image/webp"].includes(file.type))throw new Error("Use PNG, JPG, or WebP.");try{const bitmap=await createImageBitmap(file),scale=Math.min(1,1600/bitmap.width),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const context=canvas.getContext("2d");if(!context)throw new Error("Image optimization is unavailable.");context.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const optimized=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error("Could not optimize that image.")),"image/webp",0.82));if(optimized.size>1500000)throw new Error("Optimized image must be 1.5 MB or smaller.");return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error("Could not read the optimized image."));reader.readAsDataURL(optimized)})}catch(error){if(error instanceof Error&&error.message.includes("Image optimization is unavailable"))throw error;const reader=new FileReader();return await new Promise((resolve,reject)=>{reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error("Could not read that image."));reader.readAsDataURL(file)})}}

function MatchResultReview({match,matches,loading,onVerify}:{match:Match;matches:Match[];loading:boolean;onVerify?:()=>Promise<boolean>}){
 const [confirming,setConfirming]=useState(false);
 const verifyButton=useRef<HTMLButtonElement>(null);
 const players=[{id:match.participant_a,name:match.name_a,label:"Player A"},{id:match.participant_b,name:match.name_b,label:"Player B"}];
 const winner=players.find(player=>player.id&&player.id===match.winner_id);
 const other=players.find(player=>player.id&&player.id!==match.winner_id);
 const destinations=matches.flatMap(target=>(target.dependencies||[]).filter(edge=>edge.dependsOnMatchId===match.id).map(edge=>{
  const player=edge.dependencyType==="loser"?other:winner;
  const slot=advancementSlot(edge.targetSlot,match.match_order);
  const occupant=target[slot];
  return {target,player,slot,blocked:Boolean(occupant&&occupant!==player?.id)};
 }));
 const blocked=!winner||destinations.some(destination=>destination.blocked||!destination.player);
 return <div className="hof-result-review">
  <p className="hof-review-status">Awaiting verification</p>
  <section aria-labelledby="hof-result-players"><h3 id="hof-result-players">Reported result</h3>
   <div className="hof-result-players">{players.map(player=><div className="hof-result-player" key={player.label} data-winner={player===winner}>
    <small>{player.label}</small><strong>{player.name||player.label}</strong>{player===winner&&<span>Reported winner</span>}
   </div>)}</div>
  </section>
  {onVerify&&<section className="hof-result-destinations" aria-labelledby="hof-result-advancement"><h3 id="hof-result-advancement">Bracket advancement</h3>
   {destinations.length>0?<ul>{destinations.map(({target,player,slot,blocked})=><li key={`${target.id}-${slot}`}>
    <strong>{player?.name||"Entrant unavailable"}</strong>
    <span>{target.round_label} · Match {target.match_order} · {slot==="participant_a"?"Player A":"Player B"} slot</span>
    {blocked&&<small>This slot is already occupied.</small>}
   </li>)}</ul>:<p>No downstream bracket slot for this match.</p>}
  </section>}
  {!winner&&<p role="alert">The reported winner is missing. Review the match before verifying.</p>}
  {onVerify?<div className="hof-review-actions">
   {confirming?<><p>Confirm the reported result for {winner?.name||"this match"}?</p>
    <div className="actions"><button type="button" autoFocus disabled={loading} onClick={()=>{setConfirming(false);requestAnimationFrame(()=>verifyButton.current?.focus())}}>Cancel</button><button type="button" disabled={loading||blocked} onClick={async()=>{if(!await onVerify())setConfirming(false)}}>Confirm result</button></div></>:
    <button ref={verifyButton} className="hof-primary" type="button" disabled={loading||blocked} onClick={()=>setConfirming(true)}>Verify result</button>}
  </div>:<p>An organizer must verify the reported result.</p>}
 </div>;
}

function BossIdentity({boss}:{boss:Boss}){
 return <><span className="hof-boss-icon">{boss.icon_url?<img src={boss.icon_url} alt=""/>:<span aria-hidden="true">◇</span>}</span><span>{boss.name}</span></>;
}

function MatchSetupPanel({match,event,bosses,bossCatalog,draftSteps,loading,headlineBoss,onSaveBoss,onRoll,onStart,onSkip,onDraft,onReport}:{match:Match;event:Event;bosses:Boss[];bossCatalog:Boss[];draftSteps:DraftStep[]|null;loading:boolean;headlineBoss:boolean;onSaveBoss:(boss:string,method:string)=>Promise<boolean>;onRoll:()=>Promise<string|null>;onStart:()=>void;onSkip:()=>void;onDraft:(step:number,slot:string,action:string,resonator:string)=>Promise<boolean>;onReport:(winnerId:string)=>void}){
 const [boss,setBoss]=useState<string|null>(null);
 const [bossPicker,setBossPicker]=useState(false);
 const [rolling,setRolling]=useState(false);
 const [reel,setReel]=useState<Boss[]>([]);
 const [rollResult,setRollResult]=useState("");
 const slotTrigger=useRef<HTMLButtonElement>(null);
 const [pick,setPick]=useState(""),[pickerOpen,setPickerOpen]=useState(false),[search,setSearch]=useState("");
 const [winner,setWinner]=useState("");
 const order=draftOrder(event.bans_per_player===4?4:3,event.slug.startsWith("discord-hologram-"));
 const steps=draftSteps??[];
 const next=order[steps.length];
 const savedBoss=match.match_boss||"";
 const live=match.phase_state==="live";
 const expectedBoss=event.headline_boss||event.boss;
 const bossReady=Boolean(savedBoss)&&(!headlineBoss||(savedBoss.toLowerCase()===expectedBoss.toLowerCase()&&match.boss_method==="headline"));
 const canDraft=!rolling&&(bossReady||Boolean(match.started_without_details));
 const canEditBoss=!loading&&!rolling&&draftSteps!==null&&steps.length===0&&(!live||Boolean(match.started_without_details));
 const getBoss=(name:string)=>bossCatalog.find(item=>item.name===name)||{name,icon_url:""};
 const selectedBoss=boss??savedBoss;
 function closePicker(){
  setPickerOpen(false);
  setSearch("");
  slotTrigger.current?.focus();
 }
 async function rollBoss(){
  if(!canEditBoss||!bosses.length)return;
  setRolling(true);
  setBossPicker(false);
  setRollResult("");
  setReel([]);
  const result=await onRoll();
  if(!result){setRolling(false);return;}
  setBoss(null);
  const winnerBoss=getBoss(result);
  if(window.matchMedia("(prefers-reduced-motion: reduce)").matches){
   setReel([winnerBoss]);
   setRollResult(result);
   setRolling(false);
   return;
  }
  const candidates=bosses.filter(item=>item.name!==result);
  const sequence=candidates.length?candidates:bosses;
  setReel([...Array.from({length:12},(_,index)=>sequence[index%sequence.length]),winnerBoss]);
 }
 function finishRoll(){
  const winnerBoss=reel.at(-1);
  if(!winnerBoss)return;
  setReel([winnerBoss]);
  setRollResult(winnerBoss.name);
  setRolling(false);
 }
 const canStart=bossReady&&draftSteps!==null&&!next;
 const report=live&&<div className="hof-setup-panel">
  <h3>Report winner</h3>
  {savedBoss&&<p>Boss: <strong>{savedBoss}</strong></p>}
  <fieldset className="tb-winner-choice"><legend>Select the winning entrant</legend>
   {[{id:match.participant_a,name:match.name_a},{id:match.participant_b,name:match.name_b}].map(entrant=><label key={entrant.id}><input type="radio" name={`winner-${match.id}`} checked={winner===entrant.id} onChange={()=>setWinner(entrant.id||"")}/><span>{entrant.name}</span></label>)}
  </fieldset>
  <button className="hof-primary" type="button" disabled={loading||!winner} onClick={()=>onReport(winner)}>Report winner for verification</button>
 </div>;
 const setup=<div className="hof-setup-panel">
  <ol className="hof-setup-stages" aria-label="Match setup progress">
   <li aria-current={!bossReady||rolling?"step":undefined}>Boss</li><li aria-current={bossReady&&next&&!rolling?"step":undefined}>Draft</li><li aria-current={canStart?"step":undefined}>Go live</li>
  </ol>
  <section className="hof-setup-section" aria-labelledby="hof-boss-heading">
   <div className="hof-section-heading"><h3 id="hof-boss-heading">{headlineBoss?"Headline boss":"Match boss"}</h3>{steps.length>0&&<small>Locked after drafting begins</small>}</div>
   {savedBoss&&!rolling&&<div className="hof-saved-boss"><BossIdentity boss={getBoss(savedBoss)}/><small>Saved boss</small></div>}
   {headlineBoss?
    (!bossReady&&<div className="hof-setup-actions"><div className="hof-saved-boss"><BossIdentity boss={getBoss(expectedBoss)}/></div><button className="hof-primary" type="button" disabled={!canEditBoss||!expectedBoss} onClick={()=>void onSaveBoss(expectedBoss,"headline")}>Use headline boss</button></div>):
    bosses.length>0?<><div className="hof-setup-actions">
     <button type="button" disabled={!canEditBoss} aria-expanded={bossPicker} onClick={()=>{setReel([]);setRollResult("");setBossPicker(open=>!open)}}>Choose boss</button>
     <button type="button" disabled={!canEditBoss} onClick={()=>void rollBoss()}>Roll from pool</button>
     {boss&&boss!==savedBoss&&<button className="hof-primary" type="button" disabled={!canEditBoss} onClick={async()=>{if(await onSaveBoss(boss,"manual")){setBoss(null);setBossPicker(false)}}}>Save boss</button>}
    </div>
    {bossPicker&&<div className="hof-boss-options" role="group" aria-label="Event boss pool">{bosses.map(item=><button key={item.name} type="button" disabled={!canEditBoss} aria-pressed={selectedBoss===item.name} onClick={()=>setBoss(item.name)}><BossIdentity boss={item}/></button>)}</div>}
    {(rolling||reel.length>0)&&<div className="hof-roll">
     <div className="hof-reel-window" aria-hidden="true"><div className={rolling&&reel.length>1?"hof-reel-track is-spinning":"hof-reel-track"} onAnimationEnd={finishRoll}>
      {(reel.length?reel:[bosses[0]]).map((item,index)=><div className="hof-reel-item" key={index}><BossIdentity boss={item}/></div>)}
     </div></div>
     <div role="status">{rolling?"Rolling for a boss…":rollResult&&`Pool roll selected ${rollResult}`}</div>
    </div>}</>:<p>Add an eligible boss in the tournament’s Boss pool before setting up this match.</p>}
  </section>
  <section className="hof-setup-section" aria-labelledby="hof-draft-heading">
   <div className="hof-section-heading"><h3 id="hof-draft-heading">Draft · {steps.length}/{order.length}</h3>{next&&<span className="hof-current-turn">{next[0]==="a"?match.name_a:match.name_b} · {next[1]==="pick"?"Pick":"Ban"}</span>}</div>
   {!canDraft&&!rolling&&<p className="hof-setup-hint">Save a boss to unlock the draft.</p>}
   {draftSteps===null?<p role="status">Loading saved draft…</p>:<>
    <progress className="hof-draft-progress" aria-label="Draft progress" value={steps.length} max={order.length}/>
    <div className="hof-draft-teams">{(["a","b"] as const).map(slot=>{
     const player=slot==="a"?match.name_a:match.name_b;
     return <section key={slot} className="hof-draft-team" data-turn={next?.[0]===slot}>
      <h4>{player}</h4>
      {(["pick","ban"] as const).map(action=>{
       const filled=steps.filter(step=>step.actor_slot===slot&&step.action===action);
       const count=action==="pick"?3:event.bans_per_player===4?4:3;
       const label=action==="pick"?"Pick":"Ban";
       return <div key={action} className="hof-slot-row"><h5>{action==="pick"?"Team picks":"Bans"}</h5>
        <div className="hof-slots" data-count={count}>{Array.from({length:count},(_,index)=>{
         const saved=filled[index]?.resonator;
         const current=next?.[0]===slot&&next[1]===action&&index===filled.length;
         const name=saved||(current?pick:"");
         const display=featuredResonators.find(item=>item.name===name)?.displayName||name;
         return <button key={index} type="button" className="hof-draft-slot" data-action={action} data-current={current} data-filled={Boolean(name)}
          aria-label={`${player} ${label.toLowerCase()} ${index+1}${display?`: ${display}`:""}`} aria-expanded={current?pickerOpen:undefined}
          disabled={!current||loading||!canDraft} ref={current?slotTrigger:undefined} onClick={()=>pickerOpen?closePicker():setPickerOpen(true)}>
          {name?<ResonatorPortrait name={name} decorative/>:<span className="hof-slot-placeholder" aria-hidden="true">{current?"+":"–"}</span>}
          <span>{display||`${label} ${index+1}`}</span>
         </button>;
        })}</div>
       </div>;
      })}
     </section>;
    })}</div>
    {next&&pickerOpen&&canDraft&&<section className="hof-resonator-picker" aria-label="Choose Resonator">
     <div className="hof-section-heading"><h4>Choose Resonator</h4><button data-hof-picker-close type="button" onClick={closePicker}>Close picker</button></div>
     <label>Search Resonators<input autoFocus placeholder="Search by name" value={search} onChange={e=>setSearch(e.target.value)}/></label>
     <div className="hof-resonator-grid">{featuredResonators.filter(item=>`${item.name} ${item.displayName||""}`.toLowerCase().includes(search.trim().toLowerCase())).map(item=><button key={item.name} type="button"
      disabled={steps.some(step=>step.resonator.toLowerCase()===item.name.toLowerCase()&&(step.action==="ban"||next[1]==="ban"||step.actor_slot===next[0]))}
      onClick={()=>{setPick(item.name);closePicker()}}><ResonatorPortrait name={item.name} decorative/>{item.displayName||item.name}</button>)}</div>
    </section>}

   </>}
  </section>
  {(!live||Boolean(next&&pick))&&<div className="hof-setup-actions hof-setup-footer">
   {next&&pick&&<button className="hof-primary" type="button" disabled={loading||!canDraft} onClick={async()=>{if(await onDraft(steps.length+1,next[0],next[1],pick))setPick("")}}>Save draft step</button>}
   {!live&&!headlineBoss&&draftSteps&&steps.length===0&&<button type="button" disabled={loading||rolling} onClick={onSkip}>Start without details</button>}
   {!live&&<button className="hof-primary" type="button" disabled={loading||rolling||!canStart} onClick={onStart}>Go live</button>}
  </div>}
 </div>;
 return live?<>{report}{(match.started_without_details||savedBoss)&&<details><summary>{match.started_without_details?"Add setup details":"View setup details"}</summary>{setup}</details>}</>:setup;
}

